 out=R/'build/rvv-store-actor-partial-VL-v1';out.mkdir(exist_ok=False);native=R/'build/rvv-vector-store-actor-frozen-f9526584-v1';base=R/'benchmarks/rvv_store_actor_v1/guest.c';reports=[]
 for h in range(3):
  parent=R/f'build/rvv-vector-store-actor-gates-v6/positive-h{h}-seed0-ACK20';run=json.loads((parent/'run.json').read_text());build=json.loads((R/f'build/rvv-store-actor-guest-h{h}-v2/build.json').read_text())
  for n in[1,2,4,8,16,32]:
   d=out/f'h{h}-VL{n}';d.mkdir();source=d/'guest.c';text=base.read_text().replace('vl,n=64;','vl,n='+str(n)+';').replace('if(vl!=64)fail(h,1,vl,64);','if(vl!=n)fail(h,1,vl,n);').replace('bad|=output[j][i]^(3+j);','bad|=output[j][i]^(i<n?3+j:0xa5a5a5a5u);');assert text!=base.read_text();source.write_text(text);cmd=[str(source)if x==str(base)else x for x in build['argv']];cmd[-1]=str(d/'guest.elf');r=subprocess.run(cmd,capture_output=True);(d/'compile.stdout').write_bytes(r.stdout);(d/'compile.stderr').write_bytes(r.stderr);assert r.returncode==0
   argv=run['argv'][:];argv[0]=str(native/'spike');argv[-1]=str(d/'guest.elf');argv=['--extlib='+str(native/'libsifive_uart.so')if x.startswith('--extlib=')else'--iris-timing-trace='+str(d/'summary.json')if x.startswith('--iris-timing-trace=')else x for x in argv];env=dict(os.environ,IRIS_EMPIRICAL_ASYNC_TRACE=str(d/'async.jsonl'));start=time.perf_counter();r=subprocess.run(argv,env=env,capture_output=True,timeout=30);(d/'stdout').write_bytes(r.stdout);(d/'stderr').write_bytes(r.stderr);rows=[json.loads(x.split(' ',1)[1])for x in r.stdout.decode().splitlines()if x.startswith('IRIS_VSE_ACTOR {')];events=[json.loads(x)for x in(d/'async.jsonl').read_text().splitlines()];aa=[x for x in events if x.get('event')=='VSE_actor_A_beat'];dd=[x for x in events if x.get('event')=='VSE_actor_ACK_publish'];req=4*((n*4+(15 if h<2 else 31))//(16 if h<2 else 32));beats=req*(1 if h<2 else 4);checks=[r.returncode==0,len(rows)==1 and rows[0]['hart']==h and rows[0]['mismatch_or']==0 and rows[0]['checked_words']==256 and rows[0]['checksum']==18*n+4*(64-n)*0xa5a5a5a5,len(dd)==req,len(aa)==beats,sum(x['bytes']for x in dd)==4*n*4,sum(x['beat_payload_bytes']for x in aa)==4*n*4,all(x['RAM_unchanged_before_ACK']is True for x in dd)];rep=dict(hart=h,VL=n,status='passed'if all(checks)else'failed',checks=len(checks),compile_argv=cmd,argv=argv,exit_status=r.returncode,host_seconds=time.perf_counter()-start,TL_requests=len(dd),physical_A_beats=len(aa),active_bytes=16*n,independent_checked_words=256,input_sha256={str(p):sha(p)for p in[Path(__file__),base,source,Path(cmd[0]),native/'spike',native/'libsifive_uart.so',parent/'actor.fixture']},output_sha256={str(p):sha(p)for p in d.iterdir()if p.is_file()});(d/'run.json').write_text(json.dumps(rep,indent=2)+'\n');reports.append(rep)
 report=dict(schema='iris.finite_VSE32_partial_VL.v1',status='passed'if all(x['status']=='passed'for x in reports)else'failed',runs=reports,checked_poison_and_active_words=18*256,partial_wire_slots_never_published_to_RAM=True,physical_timing_certified=False,hardware_contacted=False);(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(report['status'],sha(out/'report.json'))
